// UUY-CYB 123 (Web Authoring and Development) — practice quiz bank, drawn
// note by note from src/data/lectureNotes/cyb123.js (notes 1.1-5.4), which is
// itself transcribed from the departmental Laboratory Manual ("Introduction
// to Web Programming", printed under CSC 121). It lives beside the notes for
// the same reason as cyb121Quiz.js: a catalogue that later adds this course
// imports the same bank instead of re-authoring it. Students draw a random
// sample per attempt (see CourseQuiz.jsx) and Quiz.jsx reshuffles the
// options every attempt, so no question may depend on option order.
//
// Scope matches the manual exactly: syllabus topic 7 (XSS/CSRF) is not
// covered by the lab manual and so is absent here too — CYB 122 covers web
// security separately.
export const cyb123Quiz = [
  // ── Note 1.1 — Web Programming, the Internet and the World Wide Web ──
  { question: 'Web programming is defined in the notes as:', options: ['The process of writing code that will eventually create a website', "The process of designing a computer's operating system", 'The installation of network hardware in a laboratory', "The management of a company's social media accounts"], correctIndex: 0, explanation: 'Web programming is the process of writing code that will eventually create a website — the creation of web pages that run over the Internet.' },
  { question: 'Which of these is listed among the benefits of web programming?', options: ['Guaranteed printer connectivity for every user', 'Global reach, letting businesses reach a worldwide audience', 'Removal of the need for any web server', 'A fixed, unchanging technology stack'], correctIndex: 1, explanation: 'Global reach is listed first among the benefits: the Internet and the web let businesses reach a worldwide audience with their products and services.' },
  { question: 'According to the notes, what is the Internet?', options: ['A single website hosted by a university', 'A global communication system of hardware and software providing connectivity between remote computers', 'A programming language used for building web pages', 'A protocol used specifically for encrypting email'], correctIndex: 1, explanation: 'The Internet is a global communication system consisting of hardware and software infrastructure that provides connectivity between remote computers.' },
  { question: 'The World Wide Web is best described in the notes as:', options: ['A hypermedia system of interconnected documents linked by hyperlinks and URLs', 'The physical cabling that connects computers within a building', 'A single web browser used to view pages', "A private, company-only intranet"], correctIndex: 0, explanation: 'The Web is a collection of interconnected documents and other resources, linked by hyperlinks and URLs — a hypermedia system.' },
  { question: 'In what year does the manual date the invention of the World Wide Web?', options: ['1989', '1990', '1991', '1994'], correctIndex: 3, explanation: "The manual dates the Web's invention to 1994. That is actually the year Tim Berners-Lee founded the W3C — he wrote the Web proposal in 1989 and built the first browser and server in 1990, with public release in 1991 — but the notes flag that the manual's framing is what the departmental exam expects." },
  { question: 'The three components of a URL, in the order the notes present them, are:', options: ['Protocol, server, path', 'Server, protocol, path', 'Path, protocol, server', 'Protocol, path, server'], correctIndex: 0, explanation: 'A URL breaks down into protocol (followed by a colon), server (preceded by two slashes), and path (each segment preceded by one slash).' },
  { question: 'In the URL https://www.uniuyo.edu.ng/fc/se/victoreekong.htm, what does /fc/se/ represent?', options: ['The protocol', 'The server', 'The path', 'The file extension'], correctIndex: 2, explanation: 'The path defines the location within the server where the requested item will be found — here, faculty of computing / software engineering.' },
  { question: 'Which statement about mobile devices connecting to the Internet matches the notes?', options: ['Smartphones and tablets can only connect via wireless broadband, not dial-up or Ethernet', 'Smartphones can connect via dial-up but never via Wi-Fi', 'Tablets require an Ethernet cable to reach the Internet', 'Mobile devices are incapable of connecting to the Internet at all'], correctIndex: 0, explanation: 'Mobile devices such as smartphones, tablets and iPods can only connect to wireless broadband — dial-up and Ethernet are limited to non-portable computers.' },
  { question: 'Before trusting a new Wi-Fi connection, the steps recommend testing it by:', options: ['Restarting the router twice in a row', 'Opening a reliable page such as https://www.google.com/ in a browser', 'Disabling the device\u2019s network adapter', 'Uninstalling and reinstalling the browser'], correctIndex: 1, explanation: 'Test the connection by opening a reliable site such as https://www.google.com/, so a down site does not mislead you into thinking the connection failed.' },
  { question: 'What does the notes say about dial-up Internet?', options: ['It can serve several people on the same phone line at once', 'It requires a phone line, and the connection breaks whenever that line is used for a call', 'It is faster than broadband but less reliable', 'Modern computers ship with a built-in dial-up modem'], correctIndex: 1, explanation: 'Dial-up requires a phone line and can only serve one person per phone at a time — if the phone is used for a call, the connection breaks until the call ends.' },

  // ── Note 1.2 — Internet Services and Communication Protocols ──────────
  { question: 'A network protocol is described in the notes as being like:', options: ["A diplomat's rules of behaviour when in a foreign land", 'A postal address system for computers', 'A dictionary of technical networking terms', "A company's organisational chart"], correctIndex: 0, explanation: 'Just as diplomats adhere to protocols when in a foreign land, computers must obey agreed rules — protocols — if they are to communicate with each other.' },
  { question: "How many layers does the Internet model have, compared with the OSI model's seven?", options: ['Three', 'Four', 'Five', 'Six'], correctIndex: 1, explanation: 'The Internet model is composed of just four layers: network access, internetwork, host-to-host and application — versus the seven-layer OSI model.' },
  { question: "Which OSI layers does the Internet model's application layer combine?", options: ['Physical and data link', 'Network and transport', 'Session, presentation and application', 'Transport and network'], correctIndex: 2, explanation: 'The application layer combines the functionality of the topmost three OSI layers: session, presentation and application.' },
  { question: "At the Internet model's host-to-host layer, which two protocols operate?", options: ['HTTP and FTP', 'TCP and UDP', 'SMTP and POP3', 'ARP and ICMP'], correctIndex: 1, explanation: 'The host-to-host layer is equivalent to the OSI transport layer, and its protocols are TCP and UDP.' },
  { question: 'How do TCP and UDP differ, per the notes?', options: ['TCP offers reliable, full-duplex service; UDP offers unreliable service that improves throughput', 'UDP offers reliable service; TCP sacrifices reliability for speed', 'Both offer identical reliability guarantees', 'Neither protocol offers any delivery guarantee'], correctIndex: 0, explanation: 'TCP offers reliable services and full-duplex functions; UDP provides unreliable services that improve throughput when error correction is not required.' },
  { question: 'The internetwork layer of the Internet model corresponds to which OSI layer, and uses which protocol?', options: ['Transport layer; TCP', 'Network layer; TCP/IP', 'Data link layer; Ethernet', 'Application layer; HTTP'], correctIndex: 1, explanation: 'The internetwork layer corresponds to the OSI network layer; it is responsible for routing packets, and the protocol at work here is TCP/IP.' },
  { question: 'The network access layer combines the functions of which two OSI layers?', options: ['Session and presentation', 'Transport and network', 'Physical and data link', 'Application and transport'], correctIndex: 2, explanation: 'The network access layer combines the OSI physical and data link layers, handling the exchange of data between a host and the network.' },
  { question: 'In the communication steps described, what happens to a large message before it is sent?', options: ['It is compressed into a single frame for speed', 'It is broken into smaller chunks called packets', 'It is discarded and the sender is asked to retype it', 'It is encrypted at the physical layer before anything else'], correctIndex: 1, explanation: 'If the message is large, the stack layer breaks it into smaller chunks — packets — so that data management remains stable.' },
  { question: 'Wrapping data as it travels down the protocol stack, and unwrapping it as it travels up, are respectively called:', options: ['Compression and decompression', 'Encapsulation and decapsulation', 'Routing and switching', 'Multiplexing and demultiplexing'], correctIndex: 1, explanation: 'Wrapping and unwrapping the data as it moves down and up the stack is known as encapsulation and decapsulation respectively.' },
  { question: 'Which protocol is described as connectionless and text-based, used by browsers to request pages?', options: ['FTP, for transferring files between hosts', 'SNMP, for collecting device management information', 'HTTP, through which clients send requests to web servers', 'Telnet, for remote login sessions'], correctIndex: 2, explanation: 'HTTP is a connectionless, text-based protocol through which clients (web browsers) send requests to web servers for pages and images.' },
  { question: 'Which protocol lets a user execute a session on a remote host?', options: ['SMTP, used for exchanging e-mail', 'Telnet, which enables login to another host at a remote location', 'SNMP, used for network management', 'FTP, used for transferring files between hosts'], correctIndex: 1, explanation: 'Telnet enables users to execute sessions with remote hosts, allowing login to another host at a remote location.' },

  // ── Note 1.3 — Web Architecture and the Network Model ──────────────────
  { question: 'The Web operates on a client-server architecture built around which protocol?', options: ['FTP', 'HTTP', 'SNMP', 'SMTP'], correctIndex: 1, explanation: 'The World Wide Web operates on the HyperText Transfer Protocol (HTTP), a client-server architecture where a browser interprets HTML passed by the server.' },
  { question: 'How do static and dynamic web pages differ, per the notes?', options: ['Static pages are fully interpreted at the client end; dynamic pages execute at the server and pass results to the client', 'Static pages always require a database; dynamic pages never do', 'Dynamic pages cannot contain any HTML at all', 'Static pages are inherently slower to load than dynamic pages'], correctIndex: 0, explanation: 'Static pages are fully interpreted at the client end, while dynamic pages are executed at the server end, typically running database queries, with results passed to the client.' },
  { question: "The WAP gateway's role, as described in the notes, is to:", options: ['Translate WAP requests into HTTP requests, and encode the HTTP response back into binary WML', 'Store copies of every web page for offline mobile access', 'Supply electrical power to the mobile transceiver station', 'Replace the need for a web server on the Internet side entirely'], correctIndex: 0, explanation: 'The gateway translates a WAP request into a conventional HTTP request, sends it to the Internet, then compiles the returned WML content into binary form for the phone.' },
  { question: 'Where a desktop browser interprets HTML, a WAP micro-browser interprets:', options: ['XML', 'WML', 'CSS', 'JSON'], correctIndex: 1, explanation: 'Micro-browsers on mobile phones interpret the Wireless Markup Language (WML) passed to them in the WAP architecture.' },
  { question: 'How many basic components make up a web application architecture, per the notes?', options: ['Three', 'Four', 'Five', 'Six'], correctIndex: 2, explanation: 'A web application architecture comprises five basic components: the web browser, the web server, the database server, client-side programs and server-side programs.' },
  { question: 'Which of these is one of the five components of web application architecture?', options: ['The database server, which stores, retrieves and manipulates data', 'The domain name registrar', 'The certificate authority issuing TLS certificates', 'The load balancer distributing traffic across servers'], correctIndex: 0, explanation: 'The database server is one of the five components — a DBMS such as MySQL or PostgreSQL that stores, retrieves and manipulates data.' },
  { question: 'Server-side programs in this course are described as being written in languages such as:', options: ['HTML and CSS only', 'Java Servlets/JSP, ASP, PHP, Perl, Python and CGI', 'JavaScript exclusively, since it runs everywhere', 'XML and DTD, since they define document structure'], correctIndex: 1, explanation: 'Server-side programs work with web servers to process client requests, written in languages such as Java Servlets/JSP, ASP, PHP, Perl, Python and CGI.' },
  { question: 'IIS is recommended in which scenario, according to the notes?', options: ['When both the middleware and the database server are Microsoft products, such as ASP and SQL Server', 'When the entire site is hosted on a Linux server', 'When the site serves only static HTML with no server-side logic at all', 'When the site needs to avoid using any database server'], correctIndex: 0, explanation: 'IIS is recommended where both the middleware (ASP) and the database server (SQL Server) are Microsoft products.' },
  { question: 'Apache HTTP Server is described in the notes as:', options: ['Proprietary software that only runs on Windows Server', 'Open-source software that runs on Unix, Linux, Windows and Mac OS X, serving static and dynamic content', 'A database management system for storing web content', 'A markup language used specifically for mobile devices'], correctIndex: 1, explanation: 'Apache is open-source free software that runs on Unix, Linux, MS Windows, Mac OS X and other platforms, serving static and dynamic content reliably and securely.' },

  // ── Note 1.4 — The Web Development Life Cycle ──────────────────────────
  { question: 'Which phase of the web development life cycle involves gathering information about the project and client to understand purpose and requirements?', options: ['Planning and Strategy', 'Research and Analysis', 'Designing', 'Content Creation'], correctIndex: 1, explanation: 'Research and Analysis is the first phase: gathering information about the project and client to form a clear idea of purpose, requirements and expectations.' },
  { question: 'A technology stack, as defined in the notes, is:', options: ['The set of programming languages, web frameworks and software used to build a web application', 'The physical servers that host a finished website', 'The list of employees assigned to a development team', 'The marketing budget allocated to a web project'], correctIndex: 0, explanation: 'A technology stack is the set of programming languages, web frameworks and software used to build a web application, decided during Planning and Strategy.' },
  { question: 'In the Designing phase, what is the wireframe from the Planning phase transformed into?', options: ['A fully deployed and hosted website', 'Buttons, tabs, menus, dashboards, colour schemes, typography and graphics', 'A finalised database schema', 'A server configuration file'], correctIndex: 1, explanation: 'The wireframe designed in the Planning phase is transformed into buttons, tabs, menus, dashboards, colour schemes, typography and graphics to create a base layout.' },
  { question: 'Which phase develops the branding and marketing of the web application through headlines, formatting and calls-to-action?', options: ['Development', 'Testing and Quality Assurance', 'Content Creation', 'Maintenance'], correctIndex: 2, explanation: 'Content Creation develops the branding and marketing of the web application — it is the only phase that interacts directly with converting end users into customers.' },
  { question: 'In the Development phase, which layer is responsible for managing databases, servers and logical components?', options: ['Front-end (client-side)', 'Back-end (server-side)', 'Full stack', 'The content layer'], correctIndex: 1, explanation: 'Server-side (back-end) development covers all the processes that take place behind the scenes: managing databases, servers and logical components.' },
  { question: 'Which type of developer combines both front-end and back-end work into one role?', options: ['A back-end developer', 'A front-end developer', 'A full-stack developer', 'A quality assurance engineer'], correctIndex: 2, explanation: 'Full stack combines the front end and the back end, encapsulating the whole process of website development in one role.' },
  { question: "Which of these is NOT named among the QA phase's testing activities?", options: ['Unit testing', 'Stress testing', 'Penetration testing', 'Load testing'], correctIndex: 2, explanation: 'The QA phase names unit testing, stress testing, integration testing and load testing — penetration testing is not part of this list.' },
  { question: 'What triggers the web development life cycle to run again after deployment?', options: ['A scheduled annual site rebuild', 'Continuous feedback from user interaction revealing where improvements are needed', 'A change in domain registrar', "The QA team's initial certification of the site"], correctIndex: 1, explanation: 'Continuous feedback from user interaction tells developers where improvements are needed, and the life cycle runs again to make the necessary modifications.' },

  // ── Note 2.1 — HTML Tags and Attributes ────────────────────────────────
  { question: 'HTML is best described in the notes as:', options: ['A compiled programming language', 'An interpreted scripting language', 'A markup language using predefined tags and attributes to tell the browser how to display content', 'A database query language'], correctIndex: 2, explanation: 'HTML is not a compiled or interpreted programming language; it uses predefined tags and attributes that tell the browser how to display content.' },
  { question: 'How do paired tags differ from empty tags?', options: ['Paired tags have both an opening and a closing form; empty tags stand alone with no closing tag', 'Paired tags may only appear inside <head>; empty tags only inside <body>', 'Empty tags always carry attributes, while paired tags never do', 'Paired tags were removed in HTML5'], correctIndex: 0, explanation: 'Paired tags come in opening and closing forms, like <b> and </b>; empty tags stand alone, providing metadata or inserting elements without enclosing content.' },
  { question: 'Which of the following is an example of a paired tag?', options: ['<img>', '<br>', '<b>...</b>', '<meta>'], correctIndex: 2, explanation: '<b> and its matching </b> is a paired tag; <img>, <br> and <meta> are all empty tags.' },
  { question: 'Is HTML a case-sensitive language, according to the notes?', options: ['Yes — <B> and <b> are treated as different tags', 'No — there is no difference between upper case and lower case, so ‘A’ and ‘a’ are the same', 'Only tag names are case-sensitive; attribute values are not', 'Only attribute values are case-sensitive; tag names are not'], correctIndex: 1, explanation: 'HTML is not a case-sensitive language: there is no difference between upper case and lower case, so both ‘A’ and ‘a’ are treated the same.' },

  // ── Note 2.2 — Structure of an HTML Page ───────────────────────────────
  { question: 'An HTML document is mainly divided into which two sections?', options: ['Header and footer', 'Head and body', 'Title and content', 'Metadata and script'], correctIndex: 1, explanation: 'An HTML document is mainly divided into the head, which contains metadata, and the body, which contains the visible content.' },
  { question: 'What does <!DOCTYPE html> do?', options: ['Declares the document type and version of HTML being used', 'Loads an external CSS stylesheet', "Defines the page's visible title", 'Creates a hyperlink to another document'], correctIndex: 0, explanation: 'The DOCTYPE declaration tells the browser this is an HTML5 document, declaring the document type and version.' },
  { question: 'The lang="en" attribute on the <html> tag specifies:', options: ["The document's character encoding", 'The language of the document', 'The version of HTML in use', "The page's default font family"], correctIndex: 1, explanation: 'The lang="en" attribute on the root <html> element specifies the language of the document.' },
  { question: 'Content placed inside the <head> element is:', options: ['Displayed at the very top of the visible page', 'Not displayed on the page itself', 'Displayed only when the page is printed', 'Rendered as a page footer'], correctIndex: 1, explanation: 'The <head> contains metadata — title, encoding, viewport, author and stylesheet links — none of which is displayed on the page.' },
  { question: "Which meta attribute is used to specify a page's character encoding?", options: ['name="author"', 'charset="UTF-8"', 'content="width=device-width"', 'name="description"'], correctIndex: 1, explanation: 'charset="UTF-8" on the <meta> tag specifies the character encoding used by the document.' },
  { question: 'What is the <link> tag, placed in the <head>, used for?', options: ['Creating a clickable hyperlink to another page', 'Adding or linking a CSS (cascading style sheet) file to the document', 'Defining a keyboard shortcut for the page', 'Linking two <body> sections of the same document together'], correctIndex: 1, explanation: 'The <link> tag is used to add or link a CSS (cascading style sheet) file to the HTML document.' },
  { question: 'Where does the notes say a <script> element should preferably be placed?', options: ['Only inside <head>, or at the bottom of <body>', 'Only inside the <title> element', 'Outside the <html> element entirely', 'Inside a <meta> tag'], correctIndex: 0, explanation: 'Scripts can be placed inside <head> or at the bottom of <body> to control page behaviour and interactivity.' },
  { question: 'Which tag pair is used to create an unordered (bulleted) list?', options: ['<ol> and <li>', '<ul> and <li>', '<dl> and <dt>', '<table> and <tr>'], correctIndex: 1, explanation: 'The body-elements table lists <ul>, <ol>, <li> as the unordered list, ordered list, and list item tags — an unordered list uses <ul> with <li> items.' },
  { question: 'Besides <img> for images, which other embedding tags does the body-elements table list?', options: ['<audio>, <video> and <iframe>', '<canvas> and <svg>', '<embed> and <object> only', '<picture> and <source>'], correctIndex: 0, explanation: 'The body-elements table groups <img>, <audio>, <video> and <iframe> together as the tags that embed an image, audio, video, or another page.' },

  // ── Note 2.3 — HTML Lists and Tables ───────────────────────────────────
  { question: 'An HTML table is defined in the notes as:', options: ['A group of cells organised in a two-dimensional structure of rows and columns', 'A single long paragraph of formatted text', 'A container specifically for embedding video content', 'A special type of hyperlink'], correctIndex: 0, explanation: 'A table is a group of cells organised in a two-dimensional structure with rows and columns, much like a spreadsheet.' },
  { question: 'Which tag is used to add a heading to a table column or row?', options: ['<td>', '<caption>', '<th>', '<tfoot>'], correctIndex: 2, explanation: '<th> is used to add table headings; by default its text is centred and bold.' },
  { question: 'What is the purpose of the scope attribute on a <th> element?', options: ['To indicate whether a header applies to a column, a row, or a group of either, so screen readers announce the right header for a cell', 'To set the pixel width of the entire table', 'To merge two adjacent cells into a single cell', 'To hide an entire column from the rendered page'], correctIndex: 0, explanation: 'scope shows the target data so the user does not have to rely on assumptions; it takes the values col, row, colgroup and rowgroup.' },
  { question: "In the manual's worked scope example, the top-left header cell is written as an empty <th></th>. Why?", options: ['It is a typo the manual never intended to include', 'It is deliberate — the row-number column has no natural heading, so it lines up with the Semester and Grade headers over the three data cells in every row', 'It marks the cell as hidden from screen readers', 'It tells the browser to merge that column with the next one'], correctIndex: 1, explanation: 'The empty <th></th> is the header for the row-number column; together with Semester and Grade it gives three headers matching the three <td> cells in every data row.' },
  { question: 'Which attribute lets a single table cell stretch across several rows?', options: ['colspan', 'scope', 'rowspan', 'span'], correctIndex: 2, explanation: 'rowspan lets a cell stretch across several rows, while colspan stretches a cell across several columns.' },
  { question: 'Which three elements together provide a separate table header, main content area and footer?', options: ['<caption>, <col>, <colgroup>', '<thead>, <tbody>, <tfoot>', '<th>, <td>, <tr>', '<table>, <form>, <label>'], correctIndex: 1, explanation: '<thead> provides a separate header, <tbody> contains the main content, and <tfoot> creates a separate footer.' },
  { question: 'Which is given as a reason to present data in a table rather than plain text?', options: ['It lets readers find specific information quickly by subdividing a long list', 'It guarantees the page loads faster regardless of content', 'It removes the need for a <head> element on the page', 'It disables screen reader support for that section'], correctIndex: 0, explanation: 'A table is recommended when readers need to find specific information quickly — subdividing a long list of names, for instance, makes it easy to scan.' },

  // ── Note 2.4 — HTML Forms, Graphics and Links ──────────────────────────
  { question: "The <FORM> tag's METHOD attribute accepts which two values?", options: ['GET and POST', 'SEND and RECEIVE', 'PULL and PUSH', 'READ and WRITE'], correctIndex: 0, explanation: 'The METHOD attribute accepts either POST or GET as its value, describing how the form data is sent.' },
  { question: "The manual's form-elements list includes a <radio button> element. Why is this a slip?", options: ['Because forms cannot contain radio buttons at all', "Because a radio button is an <input> with type=\"radio\", not its own separate HTML element", 'Because radio buttons must be built entirely with CSS', 'Because the real tag name is <radiobutton>, with no space'], correctIndex: 1, explanation: "There is no <radio button> element in HTML; a radio button is an <input> with type=\"radio\", exactly as the manual's own code examples show elsewhere." },
  { question: "The INPUT tag's TYPE attribute can be set to which of these values?", options: ['text, password, checkbox, radio, reset or submit', 'head, body, title or meta', 'block, inline or flex', 'get, post, put or delete'], correctIndex: 0, explanation: "TYPE decides what kind of control the <INPUT> is — among others, text, password, checkbox, radio, reset and submit."},
  { question: 'For a group of radio buttons intended to belong together, which rule applies?', options: ['Each must have a different NAME and the same VALUE', 'Each must share the same NAME, with a different VALUE for each choice', 'NAME and VALUE must both be identical across the group', 'Radio buttons cannot share a NAME attribute at all'], correctIndex: 1, explanation: 'The NAME attribute must be the same for all <INPUT> tags in one radio group, while VALUE differs for each choice.' },
  { question: "The for attribute on a <label> element associates it with an input via that input's:", options: ['name attribute', 'type attribute', 'id attribute', 'value attribute'], correctIndex: 2, explanation: "The for attribute of <label> associates it with an input through that input's id attribute." },
  { question: 'Per the note correcting the manual, which image formats are recommended for modern web use?', options: ['GIF for every kind of image', 'SVG for logos/icons, PNG for lossless detail, and WebP/AVIF for photographs', 'JPEG only, since GIF and PNG are both obsolete now', 'BMP for all images, since it is uncompressed'], correctIndex: 1, explanation: 'The note recommends SVG for logos, icons and diagrams; PNG where lossless detail or transparency is needed; and WebP/AVIF for photographs.' },
  { question: 'Why does the note warn against an image path like C:\\Dept of Software Engineering\\logo.jpg?', options: ['Because absolute local paths break as soon as the page leaves the author\u2019s own machine — a relative path should be used instead', 'Because Windows file paths are case-sensitive and HTML is not', 'Because the IMG tag does not accept a SRC attribute', 'Because spaces are illegal anywhere in a URL'], correctIndex: 0, explanation: "The manual's examples point SRC at absolute local paths that only work on the author's own machine; a relative path such as images/logo.png should be used instead." },
  { question: 'What is the purpose of the ALT attribute on an <img> tag?', options: ["It sets the image's file size in kilobytes", 'It is what screen readers announce, and what displays if the image fails to load', "It defines the image's border colour", "It compresses the image for faster page loading"], correctIndex: 1, explanation: 'ALT is what a screen reader announces for the image, and what displays in its place if the image fails to load.' },
  { question: 'Which HREF value creates a link to another section within the same document?', options: ['A HREF pointing to a mailto: address', 'A HREF beginning with # that matches a NAME anchor elsewhere in the page', 'A HREF pointing to an external website URL', 'An IMG SRC pointing to a local image file'], correctIndex: 1, explanation: '<A HREF="#section_name"> links to a matching <A NAME="section_name"> elsewhere in the same document.' },

  // ── Note 3.1 — Basics of Cascading Style Sheets ────────────────────────
  { question: 'CSS is described in the notes as the tool used for:', options: ['The structure of a web page', 'The presentation of a web page', 'Server-side processing of form data', 'The design of a database schema'], correctIndex: 1, explanation: 'CSS is the tool used for the presentation of a web page, changing how HTML content appears.' },
  { question: 'The two main parts of a CSS style rule are:', options: ['The tag and the attribute', 'The selector and the declaration', 'The header and the footer', 'The class name and the ID name'], correctIndex: 1, explanation: 'A style rule has a selector, which identifies the element(s) to affect, and a declaration, which provides the rendering instructions.' },
  { question: 'An ID selector is written using which symbol before the ID name?', options: ['A full stop (.)', 'A hash/pound sign (#)', 'An asterisk (*)', 'An at sign (@)'], correctIndex: 1, explanation: 'An ID selector is indicated with the # symbol — #recipe targets the element with id="recipe".' },
  { question: 'A CSS declaration is made up of:', options: ['A property and a value, separated by a colon', 'A selector and a tag, separated by a semicolon', 'Two selectors joined by a comma', 'A class name paired with an ID name'], correctIndex: 0, explanation: 'A declaration is a property/value pair, such as color: green, separated by a colon and a space.' },
  { question: 'Where an element name such as h1 or p is used as the selector, this is called:', options: ['An ID selector', 'A class selector', 'An element type selector', 'A universal selector'], correctIndex: 2, explanation: 'This is the most basic type of selector, an element type selector — its properties apply to every matching element in the document.' },

  // ── Note 3.2 — Adding Style to HTML, Inheritance and the Cascade ───────
  { question: 'Which of the three ways to attach styles is described as the most powerful and preferred method?', options: ['Inline styles, applied via the style attribute', 'Embedded style sheets, placed inside a <style> element', 'External style sheets, linked or imported from a separate .css file', "The browser's own default rendering"], correctIndex: 2, explanation: 'External style sheets let all files in a website share the same rules — the most powerful and preferred method for attaching styles.' },
  { question: 'Why should inline styles generally be avoided?', options: ['They cannot be overridden by any other style source at all', 'They intersperse presentation information into the structural markup and make style attributes harder to hunt down and change', 'Browsers do not reliably support the style attribute', 'They automatically apply to every element on the page, not just one'], correctIndex: 1, explanation: 'Inline styles intersperse presentation into the markup and make changes harder, since every style attribute must be found individually in the source.' },
  { question: 'Where must the <style> element be placed for embedded styling to work correctly?', options: ['Anywhere at all in the document', 'In the head of the document', 'Immediately after the closing </html> tag', 'Inside the <body> element only'], correctIndex: 1, explanation: 'An embedded style sheet is placed via the <style> element, which must be placed in the head of the document.' },
  { question: 'Which category of CSS properties tends to be passed down (inherited) by descendant elements?', options: ['Border, margin and background properties', 'Text-related properties such as font size, colour and style', 'Only properties applied through inline styles', 'None — CSS properties never inherit under any circumstances'], correctIndex: 1, explanation: 'Properties related to text styling — font size, colour, style — are passed down; properties affecting the boxed area, like borders and backgrounds, tend not to be.' },
  { question: "The manual's cascade priority chart swaps two rows compared with its own prose and the CSS specification. What is the correct order, from highest weight to lowest?", options: ['User agent styles, then user styles, then author styles', 'User !important, author !important, author normal, user normal, user agent', 'Author normal styles, user normal styles, then user !important, then author !important, then user agent', 'Author !important, user !important, user agent, then author normal, then user normal'], correctIndex: 1, explanation: "The manual's own prose gives the correct order: user !important styles rank highest, then author !important, then ordinary author styles, then ordinary user styles, then the user agent (browser) default." },
  { question: 'Between a rule targeting p and a rule targeting #intro applied to the same paragraph, which wins, and why?', options: ['The p rule always wins, because element selectors are evaluated first', 'The #intro rule wins, because an ID selector is more specific than a plain element selector', 'Neither rule applies; the browser falls back to its own default', 'The two rules are averaged together to produce a blended style'], correctIndex: 1, explanation: 'When selectors conflict, the more specific one wins — an ID selector like #intro overrides a general element selector like p.' },
  { question: 'An author style marked !important can only be overridden by:', options: ['Any later rule appearing in the same author style sheet', 'A reader/user style sheet rule that is also marked !important', 'An inline style with no !important marking of its own', 'Nothing — an !important author rule can never be overridden by anything'], correctIndex: 1, explanation: 'The only way an !important author rule may be overridden is by a conflicting rule in a reader style sheet that has also been marked !important.' },
  { question: 'When two rules of exactly equal weight conflict, which one applies?', options: ['The rule that was written first in the style sheet', 'The rule that was written last — the cascade follows a "last one wins" rule', 'Whichever rule has the shorter selector', 'The browser falls back to its own default rendering'], correctIndex: 1, explanation: 'Once priority and specificity are equal, rule order decides: whichever rule appears last has the last word.' },

  // ── Note 3.3 — CSS Text, Font and Colours; Validating Documents ────────
  { question: 'Which CSS property controls the typeface used for text?', options: ['text-align', 'font-family', 'text-transform', 'font-weight'], correctIndex: 1, explanation: 'font-family sets the typeface, alongside text-align for positioning, font-weight and text-transform for appearance, and color and font-size.' },
  { question: "A document is described as 'valid' when:", options: ['It loads in under one second on a typical connection', 'It is error-free and conforms to the rules of the HTML version in use', 'It contains no embedded CSS whatsoever', 'It has fewer than one hundred lines of markup'], correctIndex: 1, explanation: 'To validate a document is to check that the markup conforms with the rules of the HTML version in use; error-free documents are said to be valid.' },
  { question: 'Which of these is NOT listed as something an HTML validator checks?', options: ['Mismatched tags', 'Nesting errors', "The page's colour scheme and visual aesthetics", 'Non-standard elements'], correctIndex: 2, explanation: 'The validator checks DOCTYPE presence, character encoding, required attributes, non-standard elements, mismatched tags, nesting errors and typos — not aesthetics.' },
  { question: 'What benefit does the notes claim for valid, error-free documents?', options: ['They are more consistent across browsers, display more quickly, and are more accessible', 'They automatically rank higher in every search engine', 'They no longer require any CSS to render correctly', 'They are guaranteed to contain no JavaScript at all'], correctIndex: 0, explanation: 'Valid documents are more consistent across a variety of browsers, they display more quickly, and they are more accessible.' },

  // ── Note 3.4 — CSS Borders, Margin and Padding ─────────────────────────
  { question: 'In the box model described, what sits between the margin and the visible border?', options: ["Nothing — the border sits directly against the margin's edge", 'Padding, which sits inside the border, between the border and the content', "The document's viewport boundary", 'The z-index stacking layer'], correctIndex: 1, explanation: 'A margin adds space outside the element\u2019s box, a border draws a line, and padding adds space inside that border, next to the content.' },
  { question: "In the Cascade Experiment code (an @import rule, an embedded h1 rule, and an inline style on the <h1> element), which colour does the heading end up, and why?", options: ['Red, because the @import\u2019d style sheet is processed last', 'Purple, because embedded style sheets always beat inline styles', 'Blue, because the inline style appears last in the cascade and wins', 'Black, because browsers ignore inline styles entirely'], correctIndex: 2, explanation: 'The imported rule sets red, the embedded rule overrides it to purple, and the inline style — appearing last — wins with blue.' },
  { question: 'Which CSS property moves an image to one side of its container and lets text flow around it?', options: ['position', 'float', 'display', 'clear'], correctIndex: 1, explanation: 'The float property, as in img { float: right; margin: 0 12px; }, moves an image aside and lets surrounding text flow around it.' },

  // ── Note 4.1 — Basics of JavaScript ─────────────────────────────────────
  { question: 'JavaScript is described in the notes as:', options: ['A lightweight scripting language that adds interactivity and custom behaviours to Web pages', 'A markup language for structuring the content of a page', 'A database query language used by web servers', 'A compiled systems programming language'], correctIndex: 0, explanation: 'JavaScript is a lightweight scripting programming language that adds interactivity and custom behaviours to Web pages — a client-side scripting language.' },
  { question: "Whereas HTML is a page's structural layer and CSS is its presentational layer, JavaScript is described as:", options: ['The behavioural layer', 'The semantic layer', 'The transport layer', 'The accessibility layer'], correctIndex: 0, explanation: 'The third, "behavioural" layer of a page is made up of JavaScript, providing dynamic functionality and responsive interfaces.' },
  { question: 'Which of these is listed as a real-world use of JavaScript?', options: ['Autocomplete suggestions for a search box, as seen in action on google.com', 'Compiling HTML markup into machine bytecode', "Replacing the need for a web server entirely", "Defining a document's DOCTYPE declaration"], correctIndex: 0, explanation: 'Suggesting the complete term a user is typing into a search box — implemented in action on www.google.com — is the first use case listed.' },
  { question: "Scripts that fill in gaps where a browser's built-in functionality falls short, or bring newer-browser features to older browsers, are usually called:", options: ['Shims or polyfills', 'Lightboxes', 'Wrappers', 'Middleware'], correctIndex: 0, explanation: "Scripts of this kind — filling gaps in a browser's functionality or backporting newer features — are usually called shims or polyfills." },
  { question: "A 'lightbox' effect, as described in the notes, is:", options: ['A browser setting that dims everything except the active window', 'Loading an image or content into a custom-styled overlay, isolated on the page with CSS, after a thumbnail is clicked', 'A CSS property for adjusting screen brightness', "A JavaScript method for reading a device's ambient light sensor"], correctIndex: 1, explanation: 'A lightbox loads an image or content in a custom-styled overlay, isolated on the page with CSS, after a user clicks a thumbnail version of it.' },
  { question: 'For documents written in the stricter XHTML syntax, the content of a <script> element should be wrapped as:', options: ['CDATA, using // <![CDATA[ ... // ]]>', 'A second, nested <script> tag', 'A plain HTML comment <!-- ... -->', 'A <noscript> fallback block'], correctIndex: 0, explanation: "For stricter XHTML documents, the script element's content is identified as CDATA by wrapping it in // <![CDATA[ ... // ]]>." },
  { question: "Why is the recommended placement for a <script> tag at the end of the document, just before </body>?", options: ['Because by then the browser will already have finished parsing the document and its DOM structure', 'Because the <head> element is not permitted to contain any <script> tags', 'Because JavaScript files must always be loaded from an external URL', 'Because that placement disables the browser cache for the script'], correctIndex: 0, explanation: "The preferred placement is at the end of the document, before </body>, because the browser will be done parsing the document and its DOM structure by then." },
  { question: 'What is the stated downside of using an external .js script file rather than an embedded one?', options: ['Each external script requires an additional HTTP request of the server, which slows down performance', 'External scripts are unable to access the page\u2019s DOM', 'External scripts always execute before the HTML has loaded', 'Browsers block external .js files from running by default'], correctIndex: 0, explanation: 'The advantage is reuse across multiple pages; the downside is that each external script requires an additional HTTP request, slowing performance.' },
  { question: "In the manual's actual date-and-time example, which Date methods are used to build the output?", options: ['toString() and toGMTString()', 'getHours() and getMinutes()', 'toLocaleDateString() and toISOString()', 'getDay() and getMonth()'], correctIndex: 0, explanation: "The example calls now.toString() for local time and now.toGMTString() for UTC time, writing both into the page with document.write()." },
  { question: 'Why does the note warn against using document.write() in real work today?', options: ['Calling it after the page has finished loading wipes the entire document, and it is blocked outright in several modern contexts', 'No browser released in the last decade supports it at all', 'It is only capable of displaying numeric values, never text', 'It requires an active database connection to run'], correctIndex: 0, explanation: 'document.write() called after the page has loaded wipes the entire document and is blocked in several modern contexts — modern code should update a specific element instead.' },
  { question: 'Why does the note say the <!-- ... // end hiding --> wrapper inside <SCRIPT> tags can be omitted today?', options: ['It was needed only for 1990s browsers that could not understand JavaScript, and now it just obscures the code', 'It causes a hard syntax error in every browser released since 2010', 'It silently disables all event handlers attached to the page', 'It is only required inside external .js files, never inline'], correctIndex: 0, explanation: 'The comment wrapper is a relic of an era when non-JavaScript browsers would print the raw source as text; every modern browser understands <script>, so it serves no purpose now.' },

  // ── Note 4.2 — Arithmetic Operators and Functions ──────────────────────
  { question: 'Which operator performs exponentiation in JavaScript?', options: ['^', '**', '%%', 'exp()'], correctIndex: 1, explanation: 'The table lists ** for exponentiation, as in 2**3, alongside *, /, %, + and - for the other arithmetic operations.' },
  { question: 'What does the % operator compute in JavaScript?', options: ["A percentage of the first operand's value", 'The division remainder, also called the modulus', 'A concatenation of two string operands', 'A random number bounded by the two operands'], correctIndex: 1, explanation: '% is listed as the division remainder (modulus) operator, as in 5%4.' },
  { question: "In an expression like a + b, what are a and b called?", options: ['Operators', 'Operands', 'Declarations', 'Selectors'], correctIndex: 1, explanation: 'The numbers used in an arithmetic operation are called operands; the operation itself is defined by an operator and its operands.' },
  { question: 'A JavaScript function is described in the notes as:', options: ['A mini-program that is passed a value, works with it, and returns a new value to the body of the program', "A CSS style rule applied to a block of text", 'A markup tag used only for embedding external scripts', 'A definition of a database table and its columns'], correctIndex: 0, explanation: 'A function is a "mini-program": it is passed a value, works with that value, and returns a new value to the body of the program.' },
  { question: 'What are the two distinct steps involved in working with a function?', options: ['Importing it, then exporting it again', 'Declaring the function, then calling it', 'Compiling it, then linking it into the page', 'Naming it, then immediately deleting it'], correctIndex: 1, explanation: "First you declare the function, defining how it works; second you call the function in the body of your script."},
  { question: 'Where does the notes recommend declaring functions, as a rule of thumb?', options: ['In the body, right before the point where they are first used', 'In the head of the document', 'Inside a <meta> tag, so they load before anything else', 'Functions cannot be declared before they are used'], correctIndex: 1, explanation: 'A good rule, although not a strict requirement, is to declare functions in the head of the document.' },
  { question: 'Why does the note say the <!-- ... // end hiding --> wrapper around a function declaration should be omitted in modern code?', options: ['It is a relic needed only for browsers that predate widespread JavaScript support, and now only obscures the code', 'It causes the function declaration to silently fail to parse', 'It prevents the function from ever being called from the page body', 'It is required by the newer XHTML/CDATA syntax'], correctIndex: 0, explanation: "It is the same 1990s browser-hiding relic seen in the Hello World example — every browser in use today understands <script>, so it can be dropped."},

  // ── Note 4.3 — Control Statements in JavaScript ────────────────────────
  { question: "A for loop's three parts, in order, are:", options: ['Condition test, initialization, increment', 'Initialization, condition test, value alteration', 'Increment, condition test, initialization', 'Declaration, return, break'], correctIndex: 1, explanation: 'The for loop syntax is: initialize the variable; test the condition; alter the value — in that order.' },
  { question: 'Which statement runs its block only when a preceding if condition is false?', options: ['switch', 'else', 'while', 'case'], correctIndex: 1, explanation: 'else runs a block of code when the if condition evaluates to false.' },
  { question: 'In a switch statement, what does the break keyword do?', options: ['Ends the entire script immediately', 'Prevents execution from falling through into the next case', 'Declares a new local variable', 'Restarts the switch evaluation from the very first case'], correctIndex: 1, explanation: 'break stops the switch statement from falling through into the code of the next case after a match is found.' },
  { question: 'Running the Math.random() practical exercise 5000 times, what average should a student expect, and why?', options: ['Close to 1, because Math.random() is biased toward high values', 'Close to 0.5, since Math.random() draws uniformly from the range [0, 1)', 'Exactly 0, since randomness should average out to zero', 'It cannot be predicted in any way'], correctIndex: 1, explanation: 'Math.random() draws uniformly from [0, 1), so the mean of 5000 draws should land close to 0.5 — a result far from that suggests a bug in the loop, not the generator.' },

  // ── Note 4.4 — Event Handlers in JavaScript ────────────────────────────
  { question: 'An event handler is described in the notes as:', options: ['A special-purpose function used only in client-side JavaScript, defined within an HTML element\u2019s own tag', 'A CSS property that changes an element\u2019s style on hover', 'A server-side script that validates submitted form data', 'A special kind of HTML comment'], correctIndex: 0, explanation: 'Event handlers are special-purpose functions, used only in client-side JavaScript, defined as fragments of JavaScript within an element\u2019s HTML tag.' },
  { question: 'Which event fires once the browser has finished loading the entire page?', options: ['onchange', 'onload', 'onclick', 'onkeydown'], correctIndex: 1, explanation: 'onload fires once the browser has finished loading the page, or all the frames within a <FRAMESET>.' },
  { question: 'Which event handler is regularly paired with a form and a submit button to start validation scripts?', options: ['onFocus()', 'onMouseOver()', 'onSubmit()', 'onUnload()'], correctIndex: 2, explanation: 'onSubmit() fires when a form is submitted, and is regularly used to start form-validation scripts.' },
  { question: 'onFocus() fires when:', options: ['A user tabs into or clicks a form field, giving that field focus', 'The mouse pointer leaves a hyperlink or clickable image', 'The user navigates away from the current page', 'A checkbox that was checked becomes unchecked'], correctIndex: 0, explanation: 'onFocus() occurs when a user tabs into or clicks a password field, text field, textarea or file-upload field, giving it focus.' },
  { question: 'Why does the note describe document.bgColor as legacy?', options: ['It no longer works in any browser released in the last ten years', 'The modern equivalent is document.body.style.backgroundColor', 'It only works when combined with an inline style attribute', 'It was never valid JavaScript in the first place'], correctIndex: 1, explanation: 'document.bgColor is retained only for backwards compatibility; the modern equivalent is document.body.style.backgroundColor.' },
  { question: 'What does modern practice recommend instead of attaching handlers as inline HTML attributes like onClick="..."?', options: ['Writing the handler as a CSS pseudo-class rule', 'Using element.addEventListener("click", handler) in JavaScript', 'Placing the JavaScript inside an XML processing instruction', 'There is no recommended modern alternative'], correctIndex: 1, explanation: 'Modern practice attaches handlers in JavaScript via addEventListener, keeping behaviour out of the markup and letting several handlers share one element.' },

  // ── Note 5.1 — XML Basics ───────────────────────────────────────────────
  { question: 'XML is derived from which older markup standard?', options: ['HTML', 'SGML', 'DTD', 'CSS'], correctIndex: 1, explanation: 'XML is a text-based markup language derived from the Standard Generalized Markup Language (SGML).' },
  { question: 'What is the key difference between HTML tags and XML tags, per the notes?', options: ['HTML tags are used to display data; XML tags identify and store data rather than specifying how to display it', 'XML tags can never be nested inside one another', 'HTML has no tags of its own at all', 'XML tags are always empty (self-closing) tags'], correctIndex: 0, explanation: 'Where HTML tags are used to display data, XML tags identify data and are used to store and organise it rather than specifying how to display it.' },
  { question: "Which characteristic means XML lets you create your own self-descriptive tags for your application?", options: ['XML is a public standard', 'XML is extensible', 'XML carries data, it does not present it', 'XML is case-insensitive'], correctIndex: 1, explanation: '"XML is extensible" means it allows you to create your own self-descriptive tags, or language, that suits your application.' },
  { question: 'How many root elements must a well-formed XML document contain?', options: ['Zero — a root element is optional', 'Exactly one', 'Exactly two, for redundancy', 'As many as the document author prefers'], correctIndex: 1, explanation: 'Every XML document must have exactly one root element that contains all the other elements.' },

  // ── Note 5.2 — Formatting and Manipulating XML Documents ───────────────
  { question: 'If an XML declaration is present in a document, where must it appear?', options: ['Anywhere before the root element opens', 'As the very first line in the document', 'Immediately after the root element closes', 'At the very end of the document'], correctIndex: 1, explanation: 'If the XML declaration is present, it must be placed as the first line in the document.' },
  { question: 'In the XML declaration, what is the correct order of the parameters?', options: ['encoding, version, standalone', 'standalone, encoding, version', 'version, encoding, standalone', 'version, standalone, encoding'], correctIndex: 2, explanation: 'The order of the parameters matters, and the correct order is: version, encoding, standalone.' },
  { question: 'According to the syntax rules, XML parameter names and values are:', options: ['Case-insensitive throughout', 'Case-sensitive, and the names are always written in lower case', 'Only ever valid when written in upper case', 'Ignored entirely by conforming parsers'], correctIndex: 1, explanation: 'Parameter names and values are case-sensitive, and the names themselves are always in lower case.' },
  { question: 'Does the XML declaration require a closing tag?', options: ['Yes, it must be closed with </xml>', 'No — the XML declaration has no closing tag', 'Only when the standalone attribute is set to "yes"', 'Only under the XML 1.1 specification'], correctIndex: 1, explanation: 'The XML declaration has no closing tag at all — it is not treated as a paired element.' },

  // ── Note 5.3 — Viewing and Modifying XML Documents ─────────────────────
  { question: 'XML files are conventionally saved with which file extension?', options: ['.txt', '.xml', '.dtd', '.markup'], correctIndex: 1, explanation: 'XML files are saved with a .xml extension, the same way any other document is saved.' },
  { question: 'What happens when a browser opens an XML document whose start and end tags do not match?', options: ['It silently ignores the mismatch and renders the content anyway', 'It displays an error message instead of the document', 'It automatically repairs the mismatched tag names', 'It converts the document into HTML on the fly'], correctIndex: 1, explanation: 'If the tags are missing or mismatched, the browser displays an error message instead of the document.' },
  { question: 'Which of the following can be used to create or view a simple XML document?', options: ['A basic text editor such as Notepad, or a browser', 'Only a dedicated, specialised XML compiler', 'Only a full database management system', 'Only a purpose-built mobile app'], correctIndex: 0, explanation: 'An XML document can be viewed using a simple text editor or any browser — most major browsers support XML natively.' },

  // ── Note 5.4 — Processing and Validating XML Documents ─────────────────
  { question: 'A processing instruction (PI) begins and ends with which delimiters?', options: ['<! and !>', '<? and ?>', '<% and %>', '{{ and }}'], correctIndex: 1, explanation: 'A PI starts with the special tag <? and ends with ?>; processing of its contents stops as soon as ?> is encountered.' },
  { question: 'What are processing instructions mostly used for, according to the notes?', options: ['Linking an XML document to a style sheet', "Declaring the document's root element", 'Encrypting the content of the XML document', 'Defining CSS selectors used elsewhere on the page'], correctIndex: 0, explanation: "PIs are rarely used; mostly they link an XML document to a style sheet, as in <?xml-stylesheet href=\"...\" type=\"text/css\"?>." },
  { question: "An XML document is 'well-formed' when, among other rules:", options: ['Every opening tag has a matching closing tag, or is self-closing, and tags are properly nested', 'It contains no comments anywhere in the document', 'Every tag name is written entirely in upper case', 'It has no more than one child element beneath the root'], correctIndex: 0, explanation: 'Well-formed rules include that each opening tag must have a closing tag or be self-closing, and that inner tags close before their outer tags.' },
  { question: 'Which characters must be represented using predefined entities in non-DTD XML (amp, apos, gt, lt, quot)?', options: ['&, \', >, < and "', 'Only the < and > characters', 'The digits 0 through 9', 'Any whitespace character'], correctIndex: 0, explanation: 'Non-DTD XML files must use the predefined character entities for & (amp), \' (apos), > (gt), < (lt) and " (quot).' },
  { question: 'A Document Type Definition (DTD) is used to:', options: ["Style the document's visual appearance on screen", 'Define the structure — the elements, attributes and their ordering — that a valid XML document must follow', 'Compress an XML file before it is transmitted', 'Automatically convert an XML document into HTML'], correctIndex: 1, explanation: 'A DTD defines the elements, attributes and ordering an XML document must follow to be considered valid, using declarations like <!ELEMENT address (name,company,phone)>.' },
];
